<?php require_once __DIR__.'/../includes/functions.php'; verify_csrf(); if($_SERVER['REQUEST_METHOD']!=='POST')go('../login.php');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$q=db()->prepare('SELECT id,password,role,status FROM users WHERE email=?');$q->execute([$email?:'']);$u=$q->fetch();if(!$u||!password_verify($_POST['password']??'',$u['password'])||$u['status']!=='active'){flash('danger','Email or password was not recognized.');go('../login.php');}session_regenerate_id(true);$_SESSION['uid']=$u['id'];if($u['role']==='admin')go('../admin/dashboard.php');go('../student/dashboard.php');
